from locale_keys import locale
import datetime
from typing import Any
import discord
import utility
from services.ticket_service import ticket_service

async def close_ticket(interaction: discord.Interaction) -> None:
    data: Any = interaction.data
    guild = interaction.guild
    channel = interaction.channel
    assert guild is not None
    assert channel is not None
    if not data['custom_id'].startswith('ticket_close;'):
        return
    await interaction.response.defer()
    ticket_id, ticket_channel_id = (data['custom_id'].split(';')[1], data['custom_id'].split(';')[2])
    ticket_message = await ticket_service.get_config(int(ticket_id))
    if not ticket_message:
        await interaction.followup.send(locale.commands.admin.close_ticket.error.ticketNotFound1(str(interaction.locale)))
        return
    ticket = await ticket_service.get_by_config_and_channel(str(guild.id), int(ticket_id), ticket_channel_id)
    if not ticket:
        await interaction.followup.send(locale.commands.admin.close_ticket.error.ticketNotFound2(str(interaction.locale)))
        return
    ticket_channel = channel
    if not hasattr(ticket_channel, 'id') or ticket_channel.id != int(ticket.channel_id):
        await interaction.followup.send(locale.commands.admin.close_ticket.error.ticketNotFound3(str(interaction.locale)))
        return
    ticket_opener = ticket.opener_id
    ticket_opener_user = await guild.fetch_member(ticket_opener)
    ticket_open_time = ticket.opened_at
    summary_channel_id = int(ticket_message.summary_channel_id) if ticket_message.summary_channel_id else None
    summary_channel = guild.get_channel(summary_channel_id)
    if not summary_channel:
        if isinstance(channel, (discord.TextChannel, discord.Thread)):
            await channel.edit(archived=True, locked=True)
        embed = utility.tanjunEmbed(title=locale.commands.admin.close_ticket.success.ticketClosed(str(interaction.locale)), description=locale.commands.admin.close_ticket.success.ticketClosedDescription(str(interaction.locale)))
        await channel.send(embed=embed)
    else:
        html_content = await generate_summary_html(channel, ticket_opener_user, ticket_open_time)
        url = await utility.upload_to_tanjun_logs(html_content)
        embed = utility.tanjunEmbed(title=locale.commands.admin.close_ticket.success.ticketClosed(str(interaction.locale)), description=locale.commands.admin.close_ticket.success.ticketClosedDescription(str(interaction.locale), name=channel.name if hasattr(channel, 'name') else str(channel.id)))
        view = discord.ui.View()
        btn1 = discord.ui.Button(label=locale.commands.admin.close_ticket.success.viewOnlineSummary(str(interaction.locale)), url=url)
        view.add_item(btn1)
        btn2 = discord.ui.Button(label=locale.commands.admin.close_ticket.success.viewThread(str(interaction.locale)), url=f'https://discord.com/channels/{guild.id}/{ticket_channel.id}')
        view.add_item(btn2)
        await summary_channel.send(content=locale.commands.admin.close_ticket.success.ticketClosed(str(interaction.locale), user=interaction.user.mention, name=channel.name if hasattr(channel, 'name') else str(channel.id)), embed=embed, view=view)
        if isinstance(channel, discord.Thread):
            await channel.edit(archived=True, locked=True)
        await channel.send(content=locale.commands.admin.close_ticket.success.ticketClosed(str(interaction.locale), user=interaction.user.mention, name=channel.name if hasattr(channel, 'name') else str(channel.id)))

